IDCH='abcXYZ012_.-'
def rid():
    return ''.join(random.choice(IDCH) for _ in range(random.randint(1,5)))
def rb(n): return bytes(random.randrange(256) for _ in range(n)).hex()

def flow_raw(fid, nodes, replay=False, labels=None, H=None):
    H=H or random.randint(8,20)
    # ensure 4+D < H, K, exactly Q T
    roles=['K']
    # choose D count <= H-5
    maxd=H-5
    if maxd<0: maxd=0
    nd=random.randint(0,maxd)
    roles += ['D']*nd
    while len(roles)<H-2:
        roles.append(random.choice(['K','Z']))
    roles.append('Q');roles.append('T')
    random.shuffle(roles)
    # K at least1 already
    kinds=''.join(roles)
    tb=bytes(random.randrange(256) for _ in range(H))
    f={'id':fid,'path':nodes,'template':tb.hex(),'kinds':kinds}
    if replay:f['labels']=[random.randint(16,1048575) for _ in nodes]
    return f

def gen_replay():
    nn=random.randint(1,6); nodes=[rid() for _ in range(nn)]
    caps={x:random.randint(0,4) for x in nodes}
    nf=random.randint(0,5); flows=[];used=set()
    while len(flows)<nf:
        fid=rid()
        if fid in used:continue
        used.add(fid)
        L=random.randint(2,min(6,nn))
        path=random.sample(nodes,L)
        flows.append(flow_raw(fid,path,True))
    events=[]
    for _ in range(random.randint(0,100)):
        typ=random.choice(['put','enable','disable','reset','packet'])
        if typ=='put':
            if flows:
                f=random.choice(flows)
                events.append({'op':'put','flow':f['id'],'node':random.choice(f['path'])})
            else: typ='reset'
        elif typ in ('enable','disable'):
            if flows: events.append({'op':typ,'flow':random.choice(flows)['id']})
            else: typ='reset'
        if typ=='reset':events.append({'op':'reset'})
        elif typ=='packet':
            if flows:
                f=random.choice(flows)
                H=len(bytes.fromhex(f['template']))
                # create header; sometimes match K
                hb=bytearray(random.randrange(256) for _ in range(H))
                # random ttl sometimes small
                ti=f['kinds'].index('T')
                hb[ti]=random.choice([0,1,2,3,5,random.randrange(256)])
                if random.random()<.7:
                    tb=bytes.fromhex(f['template'])
                    for i,ch in enumerate(f['kinds']):
                        if ch=='K':hb[i]=tb[i]
                if random.random()<.8:
                    qi=f['kinds'].index('Q');hb[qi]=random.randrange(8)
                else:
                    qi=f['kinds'].index('Q');hb[qi]=random.randrange(8,256)
                events.append({'op':'packet','flow':f['id'],'header':bytes(hb).hex(),'payload':rb(random.randint(0,20))})
    return {'mode':'replay','capacities':caps,'flows':flows,'events':events}

# reference replay implementation independently-ish

def ref_replay(req):
    caps=req['capacities']; flows={f['id']:f for f in req['flows']}
    tables={}; enabled=set(); results=[]
    for e in req['events']:
        op=e['op']
        if op=='put':
            f=flows[e['flow']]; node=e['node']; idx=f['path'].index(node); lab=f['labels'][idx]
            tbl=tables.setdefault(node,{})
            if tbl.get(lab)==f['id']:
                results.append({'status':'ok'});continue
            busy=False
            for gid in enabled:
                g=flows[gid]
                if node in g['path'] and g['labels'][g['path'].index(node)]==lab:
                    busy=True;break
            if busy: results.append({'status':'busy'});continue
            if lab not in tbl and len(tbl)>=caps[node]:
                results.append({'status':'full'});continue
            tbl[lab]=f['id'];results.append({'status':'ok'})
        elif op=='enable':
            fid=e['flow'];f=flows[fid]
            if fid in enabled: results.append({'status':'ok'});continue
            ok=True
            for node,lab in zip(f['path'],f['labels']):
                if tables.get(node,{}).get(lab)!=fid:ok=False;break
            if ok:enabled.add(fid);results.append({'status':'ok'})
            else:results.append({'status':'unready'})
        elif op=='disable':
            enabled.discard(e['flow']);results.append({'status':'ok'})
        elif op=='reset':
            enabled.clear();results.append({'status':'ok'})
        else:
            f=flows[e['flow']];hdr=bytes.fromhex(e['header']);pay=bytes.fromhex(e['payload'])
            H=len(bytes.fromhex(f['template']));tb=bytes.fromhex(f['template']);kinds=f['kinds']
            qidx=kinds.index('Q');tidx=kinds.index('T')
            if e['flow'] not in enabled:mode='ip';reason='disabled'
            elif any(hdr[i]!=tb[i] for i,ch in enumerate(kinds) if ch=='K'):mode='ip';reason='mismatch'
            elif hdr[qidx]>7:mode='ip';reason='qos'
            else:mode='mpls';reason='compressed'
            ttl=hdr[tidx];N=len(f['path']);wire=[];bh=0;deliv=None
            if ttl>0:
                if mode=='mpls':
                    res=bytes(hdr[i] for i,ch in enumerate(kinds) if ch=='D'); q=hdr[qidx];cur=ttl
                    for i in range(N):
                        if i:
                            if cur<=1:break
                            cur-=1
                        word=(f['labels'][i]<<12)|(q<<9)|256|cur
                        w=word.to_bytes(4,'big')+res+pay;wire.append(w.hex());bh+=len(w)
                    if len(wire)==N:
                        out=bytearray(H);di=0
                        for i,ch in enumerate(kinds):
                            if ch=='K':out[i]=tb[i]
                            elif ch=='D':out[i]=res[di];di+=1
                            elif ch=='Q':out[i]=q
                            elif ch=='T':out[i]=cur
                        deliv=(bytes(out)+pay).hex()
                else:
                    hh=bytearray(hdr);cur=ttl
                    for i in range(N):
                        if i:
                            if cur<=1:break
                            cur-=1
                        hh[tidx]=cur;w=bytes(hh)+pay;wire.append(w.hex());bh+=len(w)
                    if len(wire)==N:deliv=(bytes(hh)+pay).hex()
            results.append({'mode':mode,'reason':reason,'wire':wire,'delivered':deliv,'byte_hops':bh})
    to=[]
    for node in sorted(tables):
        for lab in sorted(tables[node]):to.append({'node':node,'label':lab,'flow':tables[node][lab]})
    return {'results':results,'active':sorted(enabled),'tables':to}

# bypass strict JSON validation by direct replay expects normalized events
def run_replay_normalized(req):
    caps=m.validate_capacities(req['capacities']);flows=m.validate_flows(req['flows'],caps,True);events=m.validate_replay_events(req['events'],flows)
    # use replay by constructing? replay validates raw again
    return m.replay(req)

for t in range(3000):
