        print(json.dumps(req,indent=1));print('got',json.dumps(got,indent=1));print('exp',json.dumps(exp,indent=1));break
else:
    print('replay fuzz passed')

# planner reference brute
def brute_plan(req):
    caps=req['capacities']; flows={f['id']:f for f in req['flows']}; warm=req['warmup'];pinned=req['pinned'];offers=req['offers']
    ben={}
    for fid,f in flows.items():
        tb=bytes.fromhex(f['template']);H=len(tb);kinds=f['kinds'];qidx=kinds.index('Q');tidx=kinds.index('T');h=len(f['path'])-1
        unit=(H-4-kinds.count('D'))*len(f['path']);proc=0;el=0
        for r in offers[fid]:
            hdr=bytes.fromhex(r['header']);c=r['count'];skip=min(c,max(0,warm-proc));eff=c-skip;proc+=c
            good=all(hdr[i]==tb[i] for i,ch in enumerate(kinds) if ch=='K') and hdr[qidx]<=7 and hdr[tidx]>h
            if good:el+=eff
