    use={x:0 for x in caps}
    for fid in pinned:
        for x in flows[fid]['path']:use[x]+=1
    if any(use[x]>caps[x] for x in caps):return {'infeasible':True}
    bestv=-1;bestc=10**9;bestsel=None
    for mask in range(1<<len(ids)):
        sel=[ids[i] for i in range(len(ids)) if mask>>i&1]
        if any(fid not in sel for fid in pinned):continue
        u={x:0 for x in caps};v=0
