"""Selective header-compression protocol v1.1 model.

Reads one JSON request per line and writes one JSON response per line.
Standard library only.
"""
import sys
import json
import re
from decimal import Decimal

# ---------------------------------------------------------------------------
# JSON and schema helpers

MAX_LINE = 16 * 1024 * 1024
MAX_REPLAY_DATA = 2 * 1024 * 1024
MAX_PLAN_RUN_HEADER_DATA = 65536

ID_RE = re.compile(r'[A-Za-z0-9_.-]{1,32}')
HEX_RE = re.compile(r'[0-9a-f]*')
_BAD = object()


class InputError(Exception):
    pass


class DuplicateKey(Exception):
    pass


def _pairs(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise DuplicateKey()
        d[k] = v
    return d


def _constant(_):
    raise InputError()


def _to_int(v, lo=None, hi=None):
    """Return an integer for a finite mathematically-integral JSON number."""
    if type(v) is int:
        x = v
    elif isinstance(v, Decimal):
        try:
            if not v.is_finite() or v != v.to_integral_value():
                return _BAD
            # Check bounds before converting a potentially gigantic value.
            if lo is not None and v < lo:
                return _BAD
            if hi is not None and v > hi:
                return _BAD
            x = int(v)
        except Exception:
            return _BAD
    else:
        return _BAD
    if lo is not None and x < lo:
        return _BAD
    if hi is not None and x > hi:
        return _BAD
    return x


def _need_obj(v):
    if type(v) is not dict:
        raise InputError()
    return v


def _need_list(v):
    if type(v) is not list:
        raise InputError()
    return v


def _need_keys(d, keys):
    if type(d) is not dict or len(d) != len(keys) or set(d.keys()) != keys:
        raise InputError()


def _id(v):
    return type(v) is str and ID_RE.fullmatch(v) is not None


def _hex_bytes(v, allow_empty=True):
    if type(v) is not str or HEX_RE.fullmatch(v) is None:
        raise InputError()
    if not allow_empty and len(v) == 0:
        raise InputError()
    try:
        return bytes.fromhex(v)
    except ValueError:
        raise InputError()


def validate_capacities(v):
    if type(v) is not dict or not (1 <= len(v) <= 64):
        raise InputError()
    caps = {}
    for node, cap in v.items():
        if not _id(node):
            raise InputError()
        ci = _to_int(cap, 0, 512)
        if ci is _BAD:
            raise InputError()
        caps[node] = ci
    return caps


def validate_flow(f, caps, replay):
    if replay:
        keys = {'id', 'path', 'template', 'kinds', 'labels'}
    else:
        keys = {'id', 'path', 'template', 'kinds'}
    _need_keys(f, keys)
    fid = f['id']
    if not _id(fid):
        raise InputError()

    path = _need_list(f['path'])
    if not (2 <= len(path) <= 9):
        raise InputError()
    pset = set()
    for node in path:
        if not _id(node) or node not in caps or node in pset:
            raise InputError()
        pset.add(node)

    tb = _hex_bytes(f['template'], allow_empty=False)
    H = len(tb)
    if not (8 <= H <= 256):
        raise InputError()

    kinds = f['kinds']
    if type(kinds) is not str or len(kinds) != H:
        raise InputError()
    if any(ch not in 'KDZQT' for ch in kinds):
        raise InputError()
    if kinds.count('Q') != 1 or kinds.count('T') != 1:
        raise InputError()
    if 'K' not in kinds:
        raise InputError()
    d_idx = tuple(i for i, ch in enumerate(kinds) if ch == 'D')
    if 4 + len(d_idx) >= H:
        raise InputError()

    out = {
        'id': fid,
        'path': tuple(path),
        'path_set': pset,
        'node_index': {node: i for i, node in enumerate(path)},
        'template': tb,
        'H': H,
        'kinds': kinds,
        'k_idx': tuple(i for i, ch in enumerate(kinds) if ch == 'K'),
        'd_idx': d_idx,
        'q_idx': kinds.index('Q'),
        't_idx': kinds.index('T'),
    }

    if replay:
        labels = _need_list(f['labels'])
        if len(labels) != len(path):
            raise InputError()
        vals = []
        for x in labels:
            xi = _to_int(x, 16, 1048575)
            if xi is _BAD:
                raise InputError()
            vals.append(xi)
        out['labels'] = tuple(vals)
    return out


def validate_flows(v, caps, replay):
    flows_list = _need_list(v)
    lim = 512 if replay else 22
    if len(flows_list) > lim:
        raise InputError()
    flows = {}
    for raw in flows_list:
        _need_obj(raw)
        f = validate_flow(raw, caps, replay)
        if f['id'] in flows:
            raise InputError()
        flows[f['id']] = f
    return flows


def validate_replay_events(v, flows):
    events = _need_list(v)
    if len(events) > 20000:
        raise InputError()
    out = []
    data_total = 0
    for e in events:
        _need_obj(e)
        op = e.get('op')
        if type(op) is not str:
            raise InputError()
        if op == 'put':
            _need_keys(e, {'op', 'flow', 'node'})
            fid = e['flow']
            if not _id(fid) or fid not in flows:
                raise InputError()
            node = e['node']
            if type(node) is not str or node not in flows[fid]['path_set']:
                raise InputError()
            out.append(('put', fid, node))
        elif op == 'enable' or op == 'disable':
            _need_keys(e, {'op', 'flow'})
            fid = e['flow']
            if not _id(fid) or fid not in flows:
                raise InputError()
            out.append((op, fid))
---part2---
            out.append((op, fid))
        elif op == 'reset':
            _need_keys(e, {'op'})
            out.append(('reset',))
        elif op == 'packet':
            _need_keys(e, {'op', 'flow', 'header', 'payload'})
            fid = e['flow']
            if not _id(fid) or fid not in flows:
                raise InputError()
            f = flows[fid]
            hs = e['header']
            if type(hs) is not str or HEX_RE.fullmatch(hs) is None:
                raise InputError()
            if len(hs) // 2 != f['H']:
                raise InputError()
            ps = e['payload']
            if type(ps) is not str or HEX_RE.fullmatch(ps) is None:
                raise InputError()
            if len(ps) // 2 > 2048:
                raise InputError()
            data_total += len(hs) // 2 + len(ps) // 2
            if data_total > MAX_REPLAY_DATA:
                raise InputError()
            try:
                hb = bytes.fromhex(hs)
                pb = bytes.fromhex(ps)
            except ValueError:
                raise InputError()
            out.append(('packet', fid, hb, pb))
        else:
            raise InputError()
    return out


def validate_plan(req, caps):
    warmup = _to_int(req['warmup'], 0, 1000000000)
    if warmup is _BAD:
        raise InputError()

    flows = validate_flows(req['flows'], caps, False)
    flow_ids = set(flows)

    pinned_raw = _need_list(req['pinned'])
    pinned = []
    seen = set()
    for x in pinned_raw:
        if not _id(x) or x not in flows or x in seen:
            raise InputError()
        seen.add(x)
        pinned.append(x)

    offers_raw = _need_obj(req['offers'])
    if set(offers_raw.keys()) != flow_ids:
        raise InputError()
    offers = {}
    header_total = 0
    for fid, f in flows.items():
        runs_raw = _need_list(offers_raw[fid])
        if len(runs_raw) > 256:
            raise InputError()
        runs = []
        count_total = 0
        for r in runs_raw:
            _need_keys(r, {'header', 'count'})
            hb = _hex_bytes(r['header'], allow_empty=False)
            if len(hb) != f['H']:
                raise InputError()
            cnt = _to_int(r['count'], 1, 1000000000)
            if cnt is _BAD:
                raise InputError()
            count_total += cnt
            if count_total > 1000000000:
                raise InputError()
            header_total += len(hb)
            if header_total > MAX_PLAN_RUN_HEADER_DATA:
                raise InputError()
            runs.append((hb, cnt))
        offers[fid] = runs
    return flows, warmup, pinned, offers


