# Replay model

def replay(req):
    caps = validate_capacities(req['capacities'])
    flows = validate_flows(req['flows'], caps, True)
    events = validate_replay_events(req['events'], flows)

    tables = {}             # node -> {label: flow}
    enabled = set()
    active_uses = {}        # (node, label) -> set(flow)
    results = []

    for ev in events:
        op = ev[0]
        if op == 'put':
            _, fid, node = ev
            f = flows[fid]
            label = f['labels'][f['node_index'][node]]
            key = (node, label)
            tbl = tables.get(node)
            if tbl is not None and tbl.get(label, _BAD) == fid:
                results.append({'status': 'ok'})
                continue
            if active_uses.get(key):
                results.append({'status': 'busy'})
                continue
            if tbl is None:
                if caps[node] == 0:
                    results.append({'status': 'full'})
                    continue
                tbl = {}
                tables[node] = tbl
            elif label not in tbl:
                if len(tbl) >= caps[node]:
                    results.append({'status': 'full'})
                    continue
            # A present inactive label is overwritten without using a new slot.
            tbl[label] = fid
            results.append({'status': 'ok'})

        elif op == 'enable':
            fid = ev[1]
            if fid in enabled:
                results.append({'status': 'ok'})
                continue
            f = flows[fid]
            ok = True
            for node, label in zip(f['path'], f['labels']):
                tbl = tables.get(node)
                if tbl is None or tbl.get(label, _BAD) != fid:
                    ok = False
                    break
            if ok:
                enabled.add(fid)
                for node, label in zip(f['path'], f['labels']):
                    key = (node, label)
                    s = active_uses.get(key)
                    if s is None:
                        active_uses[key] = {fid}
                    else:
                        s.add(fid)
                results.append({'status': 'ok'})
            else:
                results.append({'status': 'unready'})

        elif op == 'disable':
            fid = ev[1]
            if fid in enabled:
                enabled.remove(fid)
                f = flows[fid]
                for node, label in zip(f['path'], f['labels']):
                    key = (node, label)
                    s = active_uses.get(key)
                    if s is not None:
                        s.discard(fid)
                        if not s:
                            del active_uses[key]
            results.append({'status': 'ok'})

        elif op == 'reset':
            enabled.clear()
            active_uses.clear()
            results.append({'status': 'ok'})

        else:  # packet
            _, fid, header, payload = ev
            f = flows[fid]
            if fid not in enabled:
                mode = 'ip'
                reason = 'disabled'
            else:
                tmpl = f['template']
                if any(header[i] != tmpl[i] for i in f['k_idx']):
                    mode = 'ip'
                    reason = 'mismatch'
                elif header[f['q_idx']] > 7:
                    mode = 'ip'
                    reason = 'qos'
                else:
                    mode = 'mpls'
                    reason = 'compressed'

            ttl = header[f['t_idx']]
            n = len(f['path'])
            wire = []
            byte_hops = 0
            delivered = None

            if ttl != 0:
                cur = ttl
                if mode == 'mpls':
                    residue = bytes(header[i] for i in f['d_idx'])
                    q = header[f['q_idx']]
                    labels = f['labels']
                    for i in range(n):
                        if i:
                            if cur <= 1:
                                break
                            cur -= 1
                        word = (labels[i] << 12) | (q << 9) | (1 << 8) | cur
                        wb = word.to_bytes(4, 'big') + residue + payload
                        wire.append(wb.hex())
                        byte_hops += len(wb)
                    if len(wire) == n:
                        out = bytearray(f['H'])
                        di = 0
                        for i, ch in enumerate(f['kinds']):
                            if ch == 'K':
                                out[i] = tmpl[i]
                            elif ch == 'D':
                                out[i] = residue[di]
                                di += 1
                            elif ch == 'Q':
                                out[i] = q
                            elif ch == 'T':
                                out[i] = cur
                            # Z remains zero
                        delivered = (bytes(out) + payload).hex()
                else:
                    hdr = bytearray(header)
                    for i in range(n):
                        if i:
                            if cur <= 1:
                                break
                            cur -= 1
                        hdr[f['t_idx']] = cur
                        wb = bytes(hdr) + payload
                        wire.append(wb.hex())
                        byte_hops += len(wb)
                    if len(wire) == n:
                        delivered = (bytes(hdr) + payload).hex()

            results.append({
                'mode': mode,
                'reason': reason,
                'wire': wire,
                'delivered': delivered,
                'byte_hops': byte_hops,
            })

    table_out = []
    for node in sorted(tables):
        for label in sorted(tables[node]):
            table_out.append({'node': node, 'label': label,
                              'flow': tables[node][label]})
    return {
        'results': results,
        'active': sorted(enabled),
        'tables': table_out,
    }


# ---------------------------------------------------------------------------
# Admission planner

class _SearchAbort(Exception):
    pass


B_ABORT_CALLS = 250000


def _planner_solve(benefits, item_nodes, caps, m):
    """Exact max-benefit / min-count 0-1 selection.

    benefits[i] > 0, item_nodes[i] is a list of binding capacity indices.
    caps[k] is the remaining capacity (each selected item consumes one).
    Returns (best_value, best_count, selected_bitmask) over m items.
    """
    if m == 0:
        return 0, 0, 0

    order = sorted(range(m), key=lambda i: -benefits[i])
    vals = [benefits[i] for i in order]
    nodes = [item_nodes[i] for i in order]
    b = len(caps)
    n = m

    suffix = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        suffix[i] = suffix[i + 1] + vals[i]

    users = [[] for _ in range(b)]
    for i in range(n):
        for k in nodes[i]:
            users[k].append(i)

    starts = []
    tails = []
    for k in range(b):
        ul = users[k]
        st = [0] * (n + 1)
        p = 0
        lu = len(ul)
        for depth in range(n + 1):
            while p < lu and ul[p] < depth:
                p += 1
            st[depth] = p
        starts.append(st)
---part3---
        starts.append(st)
        tl = [0] * (lu + 1)
        for j in range(lu - 1, -1, -1):
            tl[j] = tl[j + 1] + vals[ul[j]]
        tails.append(tl)

    # A deterministic feasible incumbent.
    gused = [0] * b
    gv = gc = gm = 0
    for i in range(n):
        ok = True
        for k in nodes[i]:
            if gused[k] >= caps[k]:
                ok = False
                break
        if ok:
            for k in nodes[i]:
                gused[k] += 1
            gv += vals[i]
            gc += 1
            gm |= (1 << i)

    best_val, best_cnt, best_mask = gv, gc, gm
    used = [0] * b
    calls = 0

    def upper_bound(i, cur):
        max_loss = 0
        for k in range(b):
            st = starts[k][i]
            ul = users[k]
            u = len(ul) - st
            allowed = caps[k] - used[k]
            if u > allowed:
                need = u - allowed
                loss = tails[k][len(ul) - need]
                if loss > max_loss:
                    max_loss = loss
        return cur + suffix[i] - max_loss

    def rec(i, cur, cnt, mask):
        nonlocal best_val, best_cnt, best_mask, calls
        calls += 1
        if calls > B_ABORT_CALLS:
            raise _SearchAbort()
        if cur > best_val or (cur == best_val and cnt < best_cnt):
            best_val, best_cnt, best_mask = cur, cnt, mask
        if i == n:
            return

        ub = upper_bound(i, cur)
        if ub < best_val:
            return
        if ub == best_val:
            need = best_val - cur
            s = 0
            t = 0
            while t < n - i and s < need:
                s += vals[i + t]
                t += 1
            if s < need or cnt + t >= best_cnt:
                return

        nds = nodes[i]
        ok = True
        for k in nds:
            if used[k] >= caps[k]:
                ok = False
                break
        if ok:
            for k in nds:
                used[k] += 1
            rec(i + 1, cur + vals[i], cnt + 1, mask | (1 << i))
            for k in nds:
                used[k] -= 1
        rec(i + 1, cur, cnt, mask)

    try:
        rec(0, 0, 0, 0)
    except _SearchAbort:
        # A completely deterministic fallback.  Subset usage vectors are
        # packed into independent 6-bit fields, so one big-integer compare
        # checks every capacity at once.
        width = 6
        packed_items = []
        for nds in nodes:
            x = 0
            for k in nds:
                x += 1 << (width * k)
            packed_items.append(x)
        cap_pack = 0
        for k in range(b):
            c = caps[k]
            if c > n:
                c = n
            cap_pack |= c << (width * k)
        highs = 0
        for k in range(b):
            highs |= 1 << (width * k + (width - 1))
        check_base = cap_pack | highs

        # The search may already have a good feasible incumbent.
        bv, bc, bm = best_val, best_cnt, best_mask
        usage = 0
        value = 0
        count = 0
        total = 1 << n
        for i in range(1, total):
            lsb = i & -i
            j = lsb.bit_length() - 1
            gray = i ^ (i >> 1)
            it = packed_items[j]
            vv = vals[j]
            if gray & lsb:
                usage += it
                value += vv
                count += 1
            else:
                usage -= it
                value -= vv
                count -= 1
            if ((check_base - usage) & highs) == highs:
                if value > bv or (value == bv and count < bc):
                    bv, bc, bm = value, count, gray
        best_val, best_cnt, best_mask = bv, bc, bm

    # Decode bits in the sorted-item coordinate system.
    selected = []
    for i in range(n):
        if (best_mask >> i) & 1:
            selected.append(order[i])
    return best_val, best_cnt, selected


def plan(req):
    caps = validate_capacities(req['capacities'])
    flows, warmup, pinned, offers = validate_plan(req, caps)

    # Compute each flow's total delivered-header savings.
    benefit = {}
    for fid, f in flows.items():
        tmpl = f['template']
        H = f['H']
        npath = len(f['path'])
        hsw = npath - 1
        unit = (H - 4 - len(f['d_idx'])) * npath
        eligible = 0
        processed = 0
        for header, cnt in offers[fid]:
            rem_warm = warmup - processed
            if rem_warm > 0:
                skip = cnt if cnt < rem_warm else rem_warm
            else:
                skip = 0
            eff = cnt - skip
            processed += cnt
            if eff <= 0:
                continue
            good = True
            for i in f['k_idx']:
                if header[i] != tmpl[i]:
                    good = False
                    break
            if good and header[f['q_idx']] > 7:
                good = False
            if good and header[f['t_idx']] <= hsw:
                good = False
            if good:
                eligible += eff
        benefit[fid] = eligible * unit

    # Apply pinned flows first.
    rem = dict(caps)
    pinned_benefit = 0
    for fid in pinned:
        for node in flows[fid]['path']:
            rem[node] -= 1
            if rem[node] < 0:
                return {'infeasible': True}
        pinned_benefit += benefit[fid]

    pinned_set = set(pinned)
    candidates = []
    for fid, f in flows.items():
        if fid in pinned_set:
            continue
        b = benefit[fid]
        if b <= 0:
            # An optional zero-benefit flow can never improve either the
            # primary or the secondary objective.
            continue
        if any(rem[node] < 1 for node in f['path']):
            continue
        candidates.append((fid, b, f['path']))

    selected = list(pinned)

    if candidates:
        all_ok = True
        all_uses = dict(caps)
        # Only the remaining capacities matter.
        for node in rem:
            all_uses[node] = 0
        for _fid, _b, path in candidates:
            for node in path:
                all_uses[node] += 1
        for node, used in all_uses.items():
            if used > rem[node]:
                all_ok = False
                break

        if all_ok:
            selected.extend(fid for fid, _b, _p in candidates)
        else:
            union_nodes = sorted({node for _fid, _b, path in candidates
                                  for node in path})
            # Constraints with capacity >= number of candidates are moot.
            binding = [node for node in union_nodes if rem[node] < len(candidates)]
            if not binding:
                selected.extend(fid for fid, _b, _p in candidates)
            else:
                bidx = {node: i for i, node in enumerate(binding)}
                item_nodes = []
                benefits = []
                ids = []
                for fid, b, path in candidates:
                    nds = []
                    for node in path:
                        k = bidx.get(node)
                        if k is not None:
                            nds.append(k)
                    # Path nodes are distinct, but sorting makes repeated
                    # membership safe in any case.
                    item_nodes.append(nds)
                    benefits.append(b)
                    ids.append(fid)
                bcap = [rem[node] for node in binding]
                _v, _c, chosen = _planner_solve(
                    benefits, item_nodes, bcap, len(candidates))
                selected.extend(ids[i] for i in chosen)

            binding = [node for node in union_nodes if rem[node] < len(candidates)]
            if not binding:
                selected.extend(fid for fid, _b, _p in candidates)
            else:
                bidx = {node: i for i, node in enumerate(binding)}
                item_nodes = []
                benefits = []
                ids = []
                for fid, b, path in candidates:
                    nds = []
                    for node in path:
                        k = bidx.get(node)
                        if k is not None:
                            nds.append(k)
                    # Path nodes are distinct, but sorting makes repeated
                    # membership safe in any case.
                    item_nodes.append(nds)
                    benefits.append(b)
                    ids.append(fid)
                bcap = [rem[node] for node in binding]
                _v, _c, chosen = _planner_solve(
                    benefits, item_nodes, bcap, len(candidates))
                selected.extend(ids[i] for i in chosen)

    selected = sorted(set(selected))
    saved = sum(benefit[fid] for fid in selected)
    return {'selected': selected, 'saved': saved}


# ---------------------------------------------------------------------------
# Request framing

def respond(req):
    _need_obj(req)
    mode = req.get('mode')
    if type(mode) is not str:
        raise InputError()
    if mode == 'replay':
        _need_keys(req, {'mode', 'capacities', 'flows', 'events'})
        return replay(req)
    if mode == 'plan':
        _need_keys(req, {'mode', 'capacities', 'flows', 'warmup',
                         'pinned', 'offers'})
        return plan(req)
    raise InputError()


def main():
    inp = sys.stdin.buffer
    out = sys.stdout
    while True:
        raw = inp.readline(MAX_LINE + 1)
        if not raw:
            break
        if len(raw) > MAX_LINE:
            # Discard the rest of this physical input line, then report one
            # malformed-line response for it.
            while not raw.endswith(b'\n'):
                raw = inp.readline(65536)
                if not raw:
                    break
            response = {'error': 'input'}
        else:
            try:
                text = raw.decode('utf-8')
                req = json.loads(text, object_pairs_hook=_pairs,
                                 parse_constant=_constant,
                                 parse_float=Decimal)
                response = respond(req)
            except Exception:
                response = {'error': 'input'}
        try:
            out.write(json.dumps(response, separators=(',', ':')) + '\n')
            out.flush()
        except BrokenPipeError:
            break


if __name__ == '__main__':
    main()

